        assert_eq!(Ring::init(&mut r.0, 64, 32).err().unwrap(), Error::TooSmall);
        assert_eq!(
            Ring::init(&mut r.0[1..], 64, 4).err().unwrap(),
            Error::Misaligned
        );
        // 32-bit tripwire: N * M wraps a 32-bit usize; the u64
