        {
            let (mut prod, mut cons) = Ring::init(&mut r.0, 64, 4).unwrap().split();
            for i in 0..2u64 {
                let mut slot = prod.reserve_slot_with::<Msg>(|_| false).unwrap();
                slot.seq = i;
                slot.val = i * 10;
