        assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
        fill(&mut prod, 4);
        drain(&mut cons, 4);
        // One more write lands in the masked-around slot 0.
        let mut slot = prod.reserve_slot_with::<Msg>(|_| false).unwrap();
        slot.seq = 4;
        slot.commit();
        let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
        assert_eq!(msg.seq, 4);
