const STREAM_CHECK_EVERY: u64 = 4096;

/// Run one streaming cell: pin (or unpin) the calling thread as
/// the producer, open the fill counters, stream a counter for
/// `dur` at `flavor` and ring `depth` to a consumer on `pin.1`,
/// and return the count, the elapsed time, and the counters.
